package com.companages.controller;
import com.companages.dto.*; import com.companages.dto.TeamDtos.*; import com.companages.entity.RecordStatus; import com.companages.service.TeamService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/organizations/{organizationId}/teams") public class TeamController { private final TeamService service; public TeamController(TeamService s){service=s;} @PostMapping ResponseEntity<Response> create(@PathVariable Long organizationId,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(organizationId,r));} @GetMapping PageResponse<Response> list(@PathVariable Long organizationId,@RequestParam(required=false)String search,@RequestParam(required=false)RecordStatus status,@PageableDefault(sort="name")Pageable pageable){return service.list(organizationId,search,status,pageable);} @GetMapping("/{id}") Response get(@PathVariable Long organizationId,@PathVariable Long id){return service.get(organizationId,id);} @PutMapping("/{id}") Response update(@PathVariable Long organizationId,@PathVariable Long id,@Valid @RequestBody Request r){return service.update(organizationId,id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void archive(@PathVariable Long organizationId,@PathVariable Long id){service.archive(organizationId,id);} @PostMapping("/{id}/restore") @ResponseStatus(HttpStatus.NO_CONTENT) void restore(@PathVariable Long organizationId,@PathVariable Long id){service.restore(organizationId,id);} }
